//! get Intl.Collator.prototype.compare
//!
//! Spec: https://tc39.es/ecma402/#sec-intl.collator.prototype.compare

use kahvi_core::function::{builtin_slots, create_builtin_function};
use kahvi_core::prelude::*;

use crate::support::intl_collator::{CollatorSlots, compare_strings};

/// get Intl.Collator.prototype.compare
pub(crate) fn prototype_get_compare(
    agent: &mut Agent,
    this: Value,
    args: &[Value],
    new_target: Option<Object>,
) -> JsResult<Value> {
    let _ = (args, new_target);
    // This named accessor property returns a function that compares two strings according to the sort order of this Collator object.
    // Intl.Collator.prototype.compare is an accessor property whose set accessor function is *undefined*. Its get accessor function performs the following steps:
    //
    // 1. Let _collator_ be the *this* value.
    // 2. Perform ? RequireInternalSlot(_collator_, [[InitializedCollator]]).
    let collator = match this {
        Value::Object(o) if agent.native::<CollatorSlots>(o).is_some() => o,
        _ => return Err(agent.throw_type_error("this is not an Intl.Collator")),
    };
    let bound = agent
        .native::<CollatorSlots>(collator)
        .and_then(|s| s.bound_compare);
    // 3. If _collator_.[[BoundCompare]] is *undefined*, then
    let bound = match bound {
        Some(b) => b,
        None => {
            // a. Let _closure_ be a new Abstract Closure with parameters (_x_, _y_) that captures _collator_ and performs the following steps when called:
            // b. Set _collator_.[[BoundCompare]] to CreateBuiltinFunction(_closure_, 2, *""*, « »).
            let empty = PropertyKey::String(agent.names.empty);
            let f = create_builtin_function(
                agent,
                compare_closure,
                2,
                empty,
                vec![Value::Object(collator)],
                None,
                None,
                None,
                false,
            );
            if let Some(slots) = agent.native_mut::<CollatorSlots>(collator) {
                slots.bound_compare = Some(f);
            }
            f
        }
    };
    // 4. Return _collator_.[[BoundCompare]].
    Ok(Value::Object(bound))
}

/// The closure of step 3.a.
fn compare_closure(
    agent: &mut Agent,
    _this: Value,
    args: &[Value],
    _new_target: Option<Object>,
) -> JsResult<Value> {
    let f = agent.active_function().expect("a running built-in");
    let Value::Object(collator) = builtin_slots(agent, f)[0] else {
        unreachable!("a compare function without its collator");
    };
    // i. Let _xString_ be ? ToString(_x_).
    let x_string = ops::to_string(agent, args.get_or_undefined(0))?;
    // ii. Let _yString_ be ? ToString(_y_).
    let y_string = ops::to_string(agent, args.get_or_undefined(1))?;
    // iii. Return CompareStrings(_collator_, _xString_, _yString_).
    let x = agent.str(x_string).to_vec();
    let y = agent.str(y_string).to_vec();
    let Some(slots) = agent.native::<CollatorSlots>(collator) else {
        unreachable!("a compare function for a non-collator");
    };
    Ok(Value::Number(compare_strings(slots, &x, &y)))
}
EOF
cat > crates/kahvi-builtins/src/intl_collator/prototype_resolved_options.rs <<'EOF'
//! Intl.Collator.prototype.resolvedOptions ( )
//!
//! Spec: https://tc39.es/ecma402/#sec-intl.collator.prototype.resolvedoptions

use kahvi_core::prelude::*;

use crate::support::intl_collator::CollatorSlots;

/// Intl.Collator.prototype.resolvedOptions
pub(crate) fn prototype_resolved_options(
    agent: &mut Agent,
    this: Value,
    args: &[Value],
    new_target: Option<Object>,
) -> JsResult<Value> {
    let _ = (args, new_target);
    // 1. Let _collator_ be the *this* value.
    // 2. Perform ? RequireInternalSlot(_collator_, [[InitializedCollator]]).
    let slots = match this {
        Value::Object(o) => agent.native::<CollatorSlots>(o),
        _ => None,
    };
    let Some(slots) = slots else {
        return Err(agent.throw_type_error("this is not an Intl.Collator"));
    };
    let locale = slots.locale.clone();
    let usage = slots.usage.clone();
    let sensitivity = slots.sensitivity.clone();
    let ignore_punctuation = slots.ignore_punctuation;
    let collation = slots.collation.clone();
    let numeric = slots.numeric;
    let case_first = slots.case_first.clone();
    // 3. Let _options_ be OrdinaryObjectCreate(%Object.prototype%).
    let object_prototype = agent.intrinsic("%Object.prototype%");
    let options = agent.ordinary_object_create(Some(object_prototype));
    // 4. For each row of [table-collator-resolvedoptions-properties], except the header row, in table order, do
    //    a. Let _propertyKey_ be the Property value of the current row.
    //    b. Let _value_ be the value of _collator_'s internal slot whose name is the Internal Slot value of the current row.
    //    c. If the current row has an Extension Key value, then
    //       i. Let _extensionKey_ be the Extension Key value of the current row.
    //       ii. If %Intl.Collator%.[[RelevantExtensionKeys]] does not contain _extensionKey_, then
    //          1. Set _value_ to *undefined*.
    //       (Both "kn" and "kf" are relevant extension keys.)
    //    d. If _value_ is not *undefined*, then
    //       i. Perform ! CreateDataPropertyOrThrow(_options_, _propertyKey_, _value_).
    let rows = [
        ("locale", Value::String(agent.string(&locale))),
        ("usage", Value::String(agent.string(&usage))),
        ("sensitivity", Value::String(agent.string(&sensitivity))),
        ("ignorePunctuation", Value::Boolean(ignore_punctuation)),
        ("collation", Value::String(agent.string(&collation))),
        ("numeric", Value::Boolean(numeric)),
        ("caseFirst", Value::String(agent.string(&case_first))),
    ];
    for (name, value) in rows {
        let key = agent.key(name);
        ops::create_data_property_or_throw(agent, options, key, value)?;
    }
    // 5. Return _options_.
    Ok(Value::Object(options))
}
